public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    // Unicode escape: \uXXXX
                    if (i + 5 < len) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                            i += 5; // skip \uXXXX
                        } catch (NumberFormatException e) {
                            throw new Exception("Invalid unicode escape: \\u" + hex);
                        }
                    } else {
                        // Not enough characters for a valid unicode escape
                        sb.append('\\').append('u');
                        i++;
                    }
                    break;
                default:
                    // Unrecognized escape, keep as is
                    sb.append(next);
                    i++;
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

