protected int removeUnusedNodes(){
    int removedCount = 0;
    try {
        CategoryNode rootNode = getRoot();
        if (rootNode == null) {
            return 0;
        }
        java.util.Deque<CategoryNode> stack = new java.util.ArrayDeque<>();
        stack.push(rootNode);
        while (!stack.isEmpty()) {
            CategoryNode current = stack.pop();
            java.util.Iterator<CategoryNode> it = current.getChildren().iterator();
            while (it.hasNext()) {
                CategoryNode child = it.next();
                if (!child.isActive()) {
                    it.remove();
                    removedCount++;
                } else {
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        // Log or handle unexpected errors gracefully
        e.printStackTrace();
    }
    return removedCount;
}

