private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate cannot be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes cannot be null");
    }

    Node current = start;

    // If the start node is already the stop node, return a circulator to it.
    if (current == stop) {
        return new OuterFaceCirculator(stop);
    }

    // Traverse the outer face in the specified direction until we hit the stop node
    // or find a node that satisfies the predicate.
    while (current != null && current != stop) {
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
        try {
            current = current.getNext(dir);
        } catch (Exception e) {
            // If traversal fails for any reason, fall back to the stop node.
            return new OuterFaceCirculator(stop);
        }
    }

    // If we exit the loop without finding a satisfying node, return the stop node.
    return new OuterFaceCirculator(stop);
}

