public int compare(Object aObj1,Object aObj2){
    if (aObj1 == aObj2) {
        return 0;
    }
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }
    // Attempt natural ordering if both are Comparable
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> c1 = (Comparable<Object>) aObj1;
            return c1.compareTo(aObj2);
        } catch (ClassCastException e) {
            // fall through to other comparison strategies
        }
    }
    // Compare by class name
    int classCmp = aObj1.getClass().getName().compareTo(aObj2.getClass().getName());
    if (classCmp != 0) {
        return classCmp;
    }
    // Compare by toString representation
    try {
        int strCmp = aObj1.toString().compareTo(aObj2.toString());
        if (strCmp != 0) {
            return strCmp;
        }
    } catch (Exception e) {
        // ignore and fall through
    }
    // Fallback to hashCode comparison
    return Integer.compare(aObj1.hashCode(), aObj2.hashCode());
}

