int addConstantNameAndType(final String name,final String descriptor){
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    // Ensure the maps/lists used by the symbol table are initialized
    if (nameAndTypeMap == null) {
        nameAndTypeMap = new java.util.HashMap<>();
    }
    if (constantPool == null) {
        constantPool = new java.util.ArrayList<>();
    }
    // Use a composite key to detect duplicates
    String key = name + "#" + descriptor;
    Integer existingIndex = nameAndTypeMap.get(key);
    if (existingIndex != null) {
        return existingIndex;
    }
    // Create a new NameAndTypeInfo instance (assumes such a class exists in the context)
    NameAndTypeInfo nt = new NameAndTypeInfo(name, descriptor);
    int newIndex = constantPool.size();
    constantPool.add(nt);
    // Cache the index for future lookups
    nameAndTypeMap.put(key, newIndex);
    return newIndex;
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char next = input.charAt(i + 1);
            if (next == '.') {
                sb.append('.');
                i++; // skip the escaped dot
            } else if (next == 'u' && i + 5 < input.length()) {
                // Attempt to parse a Unicode escape sequence \uXXXX
                String hex = input.substring(i + 2, i + 6);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                    i += 5; // skip the entire \uXXXX sequence
                } catch (NumberFormatException e) {
                    // Not a valid hex sequence; treat as literal
                    sb.append('\\').append(next);
                    i++; // skip the 'u'
                }
            } else {
                // Escape any other character (including another backslash)
                sb.append(next);
                i++; // skip the escaped character
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

