private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    java.util.List<Integer> bounds = new java.util.ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            bounds.add(0);
            continue;
        }
        if (key instanceof Integer) {
            bounds.add((Integer) key);
        } else if (key instanceof Number) {
            bounds.add(((Number) key).intValue());
        } else if (key instanceof String) {
            bounds.add(((String) key).length());
        } else {
            bounds.add(0);
        }
    }
    return bounds;
}

