static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return new String[0];
    }
    boolean hasNull = false;
    for (Object obj : array) {
        if (obj == null) {
            hasNull = true;
            break;
        }
    }
    if (!hasNull) {
        try {
            return (String[]) array;
        } catch (ClassCastException e) {
            // array is not a String[], fall through to create a new array
        }
    }
    int count = 0;
    for (Object obj : array) {
        if (obj != null) {
            count++;
        }
    }
    String[] result = new String[count];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            try {
                result[idx++] = (String) obj;
            } catch (ClassCastException e) {
                throw new IllegalArgumentException("Array contains non-String element", e);
            }
        }
    }
    return result;
}

