Edge edgeToNext() {
    try {
        if (this._currentNode == null || this._nextNode == null) {
            throw new IllegalArgumentException("Current or next node is null");
        }
        Node from = this._currentNode.isVirtual() ? this._currentNode.getRealNode() : this._currentNode;
        Node to   = this._nextNode.isVirtual()   ? this._nextNode.getRealNode()   : this._nextNode;
        if (this._edges == null) {
            return null;
        }
        for (Edge e : this._edges) {
            if (e.getFrom() == from && e.getTo() == to) {
                return e;
            }
        }
        return null;
    } catch (Exception ex) {
        throw new RuntimeException("Failed to retrieve edge to next node", ex);
    }
}

