public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        return result;
    }
    boolean filter = timeRanges != null && !timeRanges.isEmpty();
    try (java.io.ObjectInputStream ois = new java.io.ObjectInputStream(new java.io.FileInputStream(file))) {
        while (true) {
            Object obj;
            try {
                obj = ois.readObject();
            } catch (java.io.EOFException eof) {
                break;
            } catch (ClassNotFoundException cnf) {
                // Skip unknown objects
                continue;
            }
            if (obj instanceof ThreadSnapshot) {
                ThreadSnapshot snapshot = (ThreadSnapshot) obj;
                long ts = snapshot.getTimestamp();
                boolean add = !filter;
                if (filter) {
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        if (ts >= range.getStart() && ts <= range.getEnd()) {
                            add = true;
                            break;
                        }
                    }
                }
                if (add) {
                    result.add(snapshot);
                }
            }
        }
    } catch (ClassNotFoundException e) {
        throw new IOException("Failed to deserialize ThreadSnapshot", e);
    }
    return result;
}
